import { validateTargeting } from '@/lib/proxyEndpoint'
// country → ASNs that exist for it (generated by scripts/generate-asn-data.py).
// Server-only: this file is imported by routes and lib/credentials.ts, never by
// client components (they use validateTargeting from proxyEndpoint directly).
import asnIndex from '@/lib/geo/asnIndex.json'

// Shared by POST /api/v1/sub-users and POST /api/dashboard/proxies so the
// two entry points can never drift apart on what they accept. Everything is
// checked BEFORE bandwidth is reserved or upstream is touched: previously an
// unknown protocol / non-integer sticky_duration only failed at the DB CHECK
// or column type, after a reservation and a real upstream sub-user already
// existed, and surfaced as a 500 carrying the raw Postgres message.

export const MAX_GB_PER_CREDENTIAL = 100_000
export const MIN_GB_PER_CREDENTIAL = 0.01
export const MAX_STICKY_MINUTES = 1440 // 24h — the longest lifetime upstream's own dashboard produces
export const MAX_ENDPOINT_COUNT = 100
export const MAX_LABEL_LENGTH = 100

export type CreateCredentialInput = {
  label: string | null
  gb_allocated: number
  country: string | null
  state: string | null
  city: string | null
  asn: string | null
  session_type: 'rotating' | 'sticky'
  protocol: 'http' | 'socks5'
  sticky_duration: number | null
  endpoint_count: number
}

type Parsed<T> = { ok: true; value: T } | { ok: false; error: string }

// Accepts a JSON number, or a plain decimal string ("5", "0.5") — never
// NaN/Infinity, hex, exponent forms, or other coercions Number() allows.
export function parseFiniteNumber(v: unknown): number | null {
  if (typeof v === 'number') return Number.isFinite(v) ? v : null
  if (typeof v === 'string' && /^\d+(\.\d+)?$/.test(v.trim())) return Number(v.trim())
  return null
}

function parseInteger(v: unknown): number | null {
  const n = parseFiniteNumber(v)
  return n !== null && Number.isInteger(n) ? n : null
}

function optionalString(v: unknown, field: string): Parsed<string | null> {
  if (v === undefined || v === null || v === '') return { ok: true, value: null }
  if (typeof v !== 'string') return { ok: false, error: `${field} must be a string.` }
  return { ok: true, value: v.trim() || null }
}

function slugValue(v: string): string {
  return v.trim().toLowerCase().replace(/[^a-z0-9]/g, '')
}

export function parseLabel(v: unknown): Parsed<string | null> {
  if (v === undefined || v === null || v === '') return { ok: true, value: null }
  if (typeof v !== 'string') return { ok: false, error: 'label must be a string.' }
  // eslint-disable-next-line no-control-regex
  const cleaned = v.replace(/[\u0000-\u001f\u007f]/g, '').trim()
  if (cleaned.length > MAX_LABEL_LENGTH) return { ok: false, error: `label must be ${MAX_LABEL_LENGTH} characters or fewer.` }
  return { ok: true, value: cleaned || null }
}

// `checkAsn` (default true): reject an ASN that doesn't exist in the chosen
// country. Edits pass false when neither country nor ASN changed, so a legacy
// session with an ASN that has since left the inventory can still be relabelled.
export function parseTargeting(
  body: any,
  opts: { checkAsn?: boolean } = {}
): Parsed<Pick<CreateCredentialInput, 'country' | 'state' | 'city' | 'asn'>> {
  const country = optionalString(body?.country, 'country'); if (!country.ok) return country
  const state = optionalString(body?.state, 'state');       if (!state.ok) return state
  const city = optionalString(body?.city, 'city');           if (!city.ok) return city
  let asn: string | null = null
  if (body?.asn !== undefined && body?.asn !== null && body?.asn !== '') {
    if (typeof body.asn !== 'string' && typeof body.asn !== 'number') return { ok: false, error: 'asn must be a string or number.' }
    asn = String(body.asn).trim()
  }

  const err = validateTargeting({ country: country.value, state: state.value, city: city.value, asn })
  if (err) return { ok: false, error: err }

  // An ASN that isn't in the country's inventory never finds a peer: the
  // session would be created, billed against, and then fail every connection
  // with no explanation. Only checked when we actually know that country's
  // ASN list (a country absent from the index is accepted as before).
  if (asn && country.value && (opts.checkAsn ?? true)) {
    const known = (asnIndex as Record<string, string[]>)[slugValue(country.value)]
    if (known && !known.includes(asn)) {
      return { ok: false, error: `ASN ${asn} isn't available in ${country.value.toUpperCase()}. Pick one from the ISP list for that country.` }
    }
  }

  return {
    ok: true,
    value: {
      country: country.value ? slugValue(country.value) : null,
      state: state.value ? slugValue(state.value) : null,
      city: city.value ? slugValue(city.value) : null,
      asn: asn || null,
    },
  }
}

export function parseSessionOptions(body: any, defaults?: { session_type?: string; protocol?: string }): Parsed<{
  session_type: 'rotating' | 'sticky'
  protocol: 'http' | 'socks5'
  sticky_duration: number | null
}> {
  const session_type = body?.session_type ?? defaults?.session_type ?? 'rotating'
  const protocol = body?.protocol ?? defaults?.protocol ?? 'http'
  if (session_type !== 'rotating' && session_type !== 'sticky') return { ok: false, error: 'session_type must be "rotating" or "sticky".' }
  if (protocol !== 'http' && protocol !== 'socks5') return { ok: false, error: 'protocol must be "http" or "socks5".' }

  let sticky_duration: number | null = null
  if (body?.sticky_duration !== undefined && body?.sticky_duration !== null && body?.sticky_duration !== '') {
    const n = parseInteger(body.sticky_duration)
    if (n === null || n < 1 || n > MAX_STICKY_MINUTES) {
      return { ok: false, error: `sticky_duration must be a whole number of minutes between 1 and ${MAX_STICKY_MINUTES}.` }
    }
    // Only meaningful for sticky sessions; a rotating credential never uses it.
    sticky_duration = session_type === 'sticky' ? n : null
  }
  return { ok: true, value: { session_type, protocol, sticky_duration } }
}

export function parseCreateCredential(body: unknown): Parsed<CreateCredentialInput> {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return { ok: false, error: 'Request body must be a JSON object.' }
  }
  const b = body as Record<string, unknown>

  const gb = parseFiniteNumber(b.gb_allocated)
  if (gb === null || gb <= 0) return { ok: false, error: 'gb_allocated is required and must be a number > 0.' }
  if (gb < MIN_GB_PER_CREDENTIAL) return { ok: false, error: `gb_allocated must be at least ${MIN_GB_PER_CREDENTIAL}.` }
  if (gb > MAX_GB_PER_CREDENTIAL) return { ok: false, error: `gb_allocated must be at most ${MAX_GB_PER_CREDENTIAL}.` }

  const label = parseLabel(b.label); if (!label.ok) return label
  const targeting = parseTargeting(b); if (!targeting.ok) return targeting
  const session = parseSessionOptions(b); if (!session.ok) return session

  let endpoint_count = 1
  if (b.endpoint_count !== undefined && b.endpoint_count !== null && b.endpoint_count !== '') {
    const n = parseInteger(b.endpoint_count)
    if (n === null || n < 1 || n > MAX_ENDPOINT_COUNT) {
      return { ok: false, error: `endpoint_count must be a whole number between 1 and ${MAX_ENDPOINT_COUNT}.` }
    }
    endpoint_count = n
  }

  return {
    ok: true,
    value: {
      label: label.value,
      gb_allocated: Math.round(gb * 10000) / 10000,
      ...targeting.value,
      ...session.value,
      endpoint_count,
    },
  }
}

export function parseGbAmount(v: unknown, field = 'gb_amount'): Parsed<number> {
  const n = parseFiniteNumber(v)
  if (n === null || n <= 0) return { ok: false, error: `${field} must be a number greater than 0.` }
  if (n > MAX_GB_PER_CREDENTIAL) return { ok: false, error: `${field} must be at most ${MAX_GB_PER_CREDENTIAL}.` }
  const rounded = Math.round(n * 10000) / 10000
  // 0.00001 passes the > 0 check above but rounds to 0 — which used to reach the
  // database (and, for a release, the live proxy) as a zero-GB operation.
  if (rounded <= 0) return { ok: false, error: `${field} must be at least 0.0001.` }
  return { ok: true, value: rounded }
}

// ── Auto top-up configuration ─────────────────────────────────────────────
// Shared by PATCH /api/v1/sub-users/:id/auto-topup and the dashboard route.
// Bounds matter here: auto top-up spends the account balance unattended, so an
// absurd amount (1e9) or a threshold above any sub-user's possible size used to
// be accepted and then failed on every cron tick against the per-credential cap.
export type AutoTopupInput = { enabled: false } | { enabled: true; threshold_gb: number; amount_gb: number }

const hasAtMostDecimals = (n: number, d: number) => Math.abs(n * 10 ** d - Math.round(n * 10 ** d)) < 1e-6

// The optional `auto_topup` object on sub-user CREATE ({ threshold_gb, amount_gb },
// `enabled` defaulting to true — presence of the object means "turn it on").
// Returns null when absent/disabled. The shape the OpenAPI document has always
// advertised for create, which the create routes silently ignored until now.
export function parseCreateAutoTopup(raw: unknown): Parsed<{ threshold_gb: number; amount_gb: number } | null> {
  if (raw === undefined || raw === null) return { ok: true, value: null }
  if (typeof raw !== 'object' || Array.isArray(raw)) {
    return { ok: false, error: 'auto_topup must be an object: { threshold_gb, amount_gb } (optionally enabled).' }
  }
  const auto = parseAutoTopup({ enabled: true, ...(raw as object) })
  if (!auto.ok) return auto
  return { ok: true, value: auto.value.enabled ? { threshold_gb: auto.value.threshold_gb, amount_gb: auto.value.amount_gb } : null }
}

export function parseAutoTopup(body: any): Parsed<AutoTopupInput> {
  // Strictly boolean: Boolean("false") is true, so a string "false" used to
  // ENABLE auto top-up (which spends the account's balance automatically).
  if (typeof body?.enabled !== 'boolean') return { ok: false, error: 'enabled must be a boolean.' }
  if (!body.enabled) return { ok: true, value: { enabled: false } }

  const threshold = parseFiniteNumber(body.threshold_gb)
  const amount = parseFiniteNumber(body.amount_gb)
  if (threshold === null || threshold < 0) return { ok: false, error: 'threshold_gb must be a number ≥ 0' }
  if (amount === null || amount <= 0) return { ok: false, error: 'amount_gb must be a number greater than 0' }
  if (threshold > MAX_GB_PER_CREDENTIAL) return { ok: false, error: `threshold_gb cannot exceed ${MAX_GB_PER_CREDENTIAL}.` }
  if (amount < MIN_GB_PER_CREDENTIAL) return { ok: false, error: `amount_gb must be at least ${MIN_GB_PER_CREDENTIAL}.` }
  if (amount > MAX_GB_PER_CREDENTIAL) return { ok: false, error: `amount_gb cannot exceed ${MAX_GB_PER_CREDENTIAL}.` }
  if (!hasAtMostDecimals(threshold, 4) || !hasAtMostDecimals(amount, 4)) return { ok: false, error: 'threshold_gb and amount_gb can have at most 4 decimal places.' }
  // amount must exceed threshold: otherwise a top-up can leave the session
  // still at/below its own threshold and the cron re-fires every tick, draining
  // the balance into a session that never clears the line.
  if (amount <= threshold) return { ok: false, error: 'amount_gb must be greater than threshold_gb' }
  return { ok: true, value: { enabled: true, threshold_gb: threshold, amount_gb: amount } }
}
